{
  "rules": [
    "If sentiment is consistently low (≤0.2) over recent days, model tends to overestimate prices — reduce forecast by 1–3% for next period.",
    "If model shows steady upward trend with no recent dip, but true outcome shows sharp drop, adjust forecast downward by 2–5% to account for mean reversion.",
    "After a spike in price (e.g., >88), model often overshoots — cap forecast at +2% above peak or use 10-day moving average to smooth.",
    "When sentiment is positive (≥0.2) and model is flat or rising, expect volatility — add 1–2% buffer for downward correction if true outcome dips.",
    "If true outcome deviates >5% from forecast in first 5 days, assume model is lagging — adjust forecast to match recent 3-day average of true values.",
    "If sentiment history shows repeated 0.00 values, model is likely underestimating — increase forecast by 1–3% to account for suppressed sentiment bias."
  ]
}
